CREATE OR REPLACE FUNCTION public.respond_neroxa_public_proposal(p_token uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  proposal public.neroxa_proposals;
  next_status text;
begin
  if p_action not in ('ACCEPTED','REJECTED') then
    raise exception 'Ação inválida.';
  end if;

  select * into proposal
  from public.neroxa_proposals
  where public_token = p_token
  for update;

  if not found then
    raise exception 'Proposta não encontrada.';
  end if;

  if proposal.status not in ('SENT','NEGOTIATION') then
    raise exception 'Esta proposta não está disponível para resposta.';
  end if;

  if proposal.valid_until is not null and proposal.valid_until < current_date then
    update public.neroxa_proposals
      set status = 'EXPIRED', updated_at = now()
      where id = proposal.id;
    raise exception 'Esta proposta expirou.';
  end if;

  next_status := p_action;
  update public.neroxa_proposals
    set status = next_status,
        accepted_at = case when next_status = 'ACCEPTED' then now() else accepted_at end,
        rejected_at = case when next_status = 'REJECTED' then now() else rejected_at end,
        updated_at = now()
    where id = proposal.id;

  insert into public.neroxa_audit_logs(actor_id, organization_id, action, resource_type, resource_id, details)
  values (
    null,
    proposal.client_id,
    'PROPOSAL_PUBLIC_RESPONSE',
    'PROPOSAL',
    proposal.id,
    jsonb_build_object('status', next_status, 'channel', 'PUBLIC_LINK')
  );

  return jsonb_build_object('id', proposal.id, 'status', next_status);
end;
$function$

CREATE OR REPLACE FUNCTION public.retry_neroxa_provisioning_job(p_job_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_job public.neroxa_provisioning_jobs%rowtype;
  v_instance public.neroxa_system_instances%rowtype;
  v_existing uuid;
  v_new_job uuid;
begin
  if not public.neroxa_has_platform_role(array[
    'SUPER_ADMIN'::public.neroxa_platform_role,
    'ADMIN'::public.neroxa_platform_role,
    'SUPPORT'::public.neroxa_platform_role
  ]) then
    raise exception 'Sem permissão para tentar novamente o provisionamento';
  end if;

  select * into v_job from public.neroxa_provisioning_jobs
  where id=p_job_id for update;
  if not found then raise exception 'Job de provisionamento não encontrado'; end if;
  if v_job.status not in ('FAILED','CANCELLED') then
    raise exception 'Somente jobs falhos ou cancelados podem ser tentados novamente';
  end if;
  if v_job.system_instance_id is null then
    raise exception 'O job não está vinculado a uma instância';
  end if;

  select * into v_instance from public.neroxa_system_instances
  where id=v_job.system_instance_id for update;
  if not found then raise exception 'Instância do job não encontrada'; end if;
  if v_instance.status='ARCHIVED' then
    raise exception 'Uma instância arquivada não pode receber novo provisionamento';
  end if;

  select id into v_existing from public.neroxa_provisioning_jobs
  where system_instance_id=v_instance.id
    and status in ('PENDING','RUNNING')
    and id<>v_job.id
  order by created_at desc,id desc limit 1;
  if v_existing is not null then
    raise exception 'Já existe um job de provisionamento ativo para esta instância';
  end if;

  perform set_config('neroxa.implementation_write_path','official',true);

  insert into public.neroxa_provisioning_jobs
    (organization_id,system_instance_id,action,status,payload)
  values
    (v_job.organization_id,v_job.system_instance_id,v_job.action,'PENDING',
     jsonb_set(coalesce(v_job.payload,'{}'::jsonb),'{retry}','true'::jsonb,true))
  returning id into v_new_job;

  return v_new_job;
end;
$function$

CREATE OR REPLACE FUNCTION public.send_neroxa_contract_for_signature(p_contract_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_contract public.neroxa_contracts%rowtype;
  v_number text;
  v_profile jsonb;
  v_legal_name text;
  v_trade_name text;
  v_tax_id text;
  v_signer_name text;
  v_signer_role text;
begin
  if not public.neroxa_has_platform_role(array['SUPER_ADMIN'::public.neroxa_platform_role, 'ADMIN'::public.neroxa_platform_role]) then
    raise exception 'Sem permissão para enviar contratos para assinatura';
  end if;

  select * into v_contract from public.neroxa_contracts where id = p_contract_id for update;
  if not found then raise exception 'Contrato não encontrado'; end if;
  if v_contract.status <> 'DRAFT' then raise exception 'Somente contratos em rascunho podem ser enviados para assinatura'; end if;

  if v_contract.proposal_id is not null and not exists (
    select 1 from public.neroxa_proposals p
    where p.id = v_contract.proposal_id and p.status = 'ACCEPTED'
  ) then
    raise exception 'O contrato só pode ser enviado após a aceitação da proposta vinculada';
  end if;

  select value into v_profile from public.neroxa_platform_settings where key = 'legal_profile' limit 1;

  v_legal_name := btrim(coalesce(v_profile->>'legal_name', ''));
  v_trade_name := btrim(coalesce(v_profile->>'trade_name', ''));
  v_tax_id := btrim(coalesce(v_profile->>'tax_id', ''));
  v_signer_name := btrim(coalesce(v_profile->>'signer_name', ''));
  v_signer_role := btrim(coalesce(v_profile->>'signer_role', ''));

  if v_legal_name = '' then raise exception 'Configure o nome completo da prestadora em Configurações > Identificação da Neroxa'; end if;
  if v_tax_id = '' then raise exception 'Configure o CPF da prestadora em Configurações > Identificação da Neroxa'; end if;
  if v_signer_name = '' then raise exception 'Configure o responsável pela assinatura da Neroxa em Configurações > Identificação da Neroxa'; end if;
  if v_signer_role = '' then raise exception 'Configure o cargo do responsável pela Neroxa em Configurações > Identificação da Neroxa'; end if;

  if coalesce(btrim(v_contract.contract_number), '') = '' then
    v_number := 'NRX-' || to_char(current_date, 'YYYY') || '-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
  else
    v_number := v_contract.contract_number;
  end if;

  update public.neroxa_contracts
  set
    contract_number = v_number,
    issued_at = coalesce(issued_at, now()),
    signature_status = 'PENDING_CUSTOMER',
    signature_requested_at = now(),
    neroxa_entity_type = 'INDIVIDUAL',
    neroxa_trade_name = coalesce(nullif(v_trade_name, ''), 'Neroxa | Soluções Personalizadas'),
    neroxa_legal_name = v_legal_name,
    neroxa_tax_id = v_tax_id,
    neroxa_signer_name = v_signer_name,
    neroxa_signer_role = v_signer_role
  where id = p_contract_id;

  return p_contract_id;
end;
$function$

