CREATE OR REPLACE FUNCTION public.transition_neroxa_domain_status(p_domain_id uuid, p_new_status neroxa_domain_status)
 RETURNS neroxa_domain_status
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_domain public.neroxa_system_domains%rowtype;
  v_instance public.neroxa_system_instances%rowtype;
  v_allowed boolean := false;
begin
  if not public.neroxa_has_platform_role(array[
    'SUPER_ADMIN'::public.neroxa_platform_role,
    'ADMIN'::public.neroxa_platform_role,
    'SUPPORT'::public.neroxa_platform_role
  ]) then
    raise exception 'Sem permissão para gerenciar domínios';
  end if;

  select * into v_domain
  from public.neroxa_system_domains
  where id = p_domain_id
  for update;

  if not found then
    raise exception 'Domínio não encontrado';
  end if;

  select * into v_instance
  from public.neroxa_system_instances
  where id = v_domain.system_instance_id
  for update;

  if not found then
    raise exception 'Instância do domínio não encontrada';
  end if;

  if v_instance.status = 'ARCHIVED' then
    raise exception 'Instâncias arquivadas não podem ter o domínio validado';
  end if;

  v_allowed := case v_domain.status
    when 'PENDING' then p_new_status in ('VERIFYING','DISABLED')
    when 'VERIFYING' then p_new_status in ('VERIFIED','FAILED','DISABLED')
    when 'FAILED' then p_new_status in ('VERIFYING','DISABLED')
    when 'VERIFIED' then p_new_status = 'DISABLED'
    when 'DISABLED' then p_new_status = 'VERIFYING'
    else false
  end;

  if not v_allowed then
    raise exception 'Transição de domínio não permitida: % -> %', v_domain.status, p_new_status;
  end if;

  update public.neroxa_system_domains
  set status = p_new_status,
      verified_at = case
        when p_new_status = 'VERIFIED' then now()
        else null
      end,
      updated_at = now()
  where id = p_domain_id;

  perform public.record_neroxa_audit(
    case
      when p_new_status = 'VERIFYING' then 'DOMAIN_VALIDATION_STARTED'
      when p_new_status = 'VERIFIED' then 'DOMAIN_VALIDATED'
      when p_new_status = 'FAILED' then 'DOMAIN_VALIDATION_FAILED'
      when p_new_status = 'DISABLED' then 'DOMAIN_DISABLED'
      else 'DOMAIN_STATUS_CHANGED'
    end,
    'SYSTEM_DOMAIN',
    p_domain_id,
    v_instance.organization_id,
    jsonb_build_object(
      'domain', v_domain.domain,
      'previous_status', v_domain.status,
      'new_status', p_new_status,
      'system_instance_id', v_domain.system_instance_id
    )
  );

  return p_new_status;
end;
$function$

CREATE OR REPLACE FUNCTION public.transition_neroxa_instance_status(p_instance_id uuid, p_status neroxa_instance_status)
 RETURNS neroxa_instance_status
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_instance public.neroxa_system_instances%rowtype;
begin
  if not public.neroxa_has_platform_role(array['SUPER_ADMIN'::public.neroxa_platform_role,'ADMIN'::public.neroxa_platform_role,'SUPPORT'::public.neroxa_platform_role]) then raise exception 'Sem permissão para alterar o status da instância'; end if;
  select * into v_instance from public.neroxa_system_instances where id=p_instance_id for update;
  if not found then raise exception 'Instância não encontrada'; end if;
  if v_instance.status=p_status then return v_instance.status; end if;
  if v_instance.status='ARCHIVED' then raise exception 'Uma instância arquivada não pode ter o status alterado'; end if;
  if v_instance.status='PROVISIONING' and p_status not in ('ACTIVE','SUSPENDED','ARCHIVED') then raise exception 'Uma instância em provisionamento só pode ficar ativa, suspensa ou arquivada'; end if;
  if v_instance.status='ACTIVE' and p_status not in ('SUSPENDED','ARCHIVED') then raise exception 'Uma instância ativa só pode ser suspensa ou arquivada'; end if;
  if v_instance.status='SUSPENDED' and p_status not in ('ACTIVE','ARCHIVED') then raise exception 'Uma instância suspensa só pode ser reativada ou arquivada'; end if;
  update public.neroxa_system_instances set status=p_status,updated_at=now() where id=p_instance_id;
  return p_status;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_admin_order_status(p_order_id uuid, p_status text, p_note text DEFAULT NULL::text)
 RETURNS neroxa_orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_order public.neroxa_orders; v_old text;
begin
 if not public.neroxa_is_platform_member() then raise exception 'Acesso negado'; end if;
 select * into v_order from public.neroxa_orders where id=p_order_id for update;
 if not found then raise exception 'Pedido não encontrado'; end if;
 if p_status not in ('RECEIVED','CONFIRMED','PREPARING','READY','OUT_FOR_DELIVERY','DELIVERED','CANCELLED') then raise exception 'Status inválido'; end if;
 v_old:=v_order.status;
 update public.neroxa_orders set status=p_status,updated_at=now(),
 confirmed_at=case when p_status='CONFIRMED' and confirmed_at is null then now() else confirmed_at end,
 preparing_at=case when p_status='PREPARING' and preparing_at is null then now() else preparing_at end,
 ready_at=case when p_status='READY' and ready_at is null then now() else ready_at end,
 out_for_delivery_at=case when p_status='OUT_FOR_DELIVERY' and out_for_delivery_at is null then now() else out_for_delivery_at end,
 delivered_at=case when p_status='DELIVERED' and delivered_at is null then now() else delivered_at end,
 cancelled_at=case when p_status='CANCELLED' and cancelled_at is null then now() else cancelled_at end
 where id=p_order_id returning * into v_order;
 insert into public.neroxa_order_status_history(order_id,from_status,to_status,changed_by_user_id,note)
 values(p_order_id,v_old,p_status,auth.uid(),nullif(trim(p_note),''));
 return v_order;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_neroxa_provisioning_job_status(p_job_id uuid, p_status neroxa_provisioning_status, p_error_message text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_job public.neroxa_provisioning_jobs%rowtype;
  v_latest_status public.neroxa_provisioning_status;
  v_now timestamptz := now();
begin
  if not public.neroxa_has_platform_role(array[
    'SUPER_ADMIN'::public.neroxa_platform_role,
    'ADMIN'::public.neroxa_platform_role,
    'SUPPORT'::public.neroxa_platform_role
  ]) then
    raise exception 'Sem permissão para atualizar o job de implantação';
  end if;

  select *
    into v_job
    from public.neroxa_provisioning_jobs
   where id = p_job_id
   for update;

  if not found then
    raise exception 'Job de implantação não encontrado';
  end if;

  if v_job.status in ('COMPLETED', 'FAILED', 'CANCELLED') then
    raise exception 'O job de implantação já foi encerrado';
  end if;

  if v_job.status = 'PENDING' and p_status not in ('RUNNING', 'FAILED', 'CANCELLED') then
    raise exception 'Um job pendente só pode iniciar, falhar ou ser cancelado';
  end if;

  if v_job.status = 'RUNNING' and p_status not in ('COMPLETED', 'FAILED', 'CANCELLED') then
    raise exception 'Um job em execução só pode concluir, falhar ou ser cancelado';
  end if;

  if v_job.system_instance_id is not null then
    perform 1
      from public.neroxa_system_instances
     where id = v_job.system_instance_id
     for update;

    if not found then
      raise exception 'Instância da implantação não encontrada';
    end if;
  end if;

  update public.neroxa_provisioning_jobs
     set status = p_status,
         error_message = case
           when p_status = 'FAILED' then nullif(trim(coalesce(p_error_message, '')), '')
           else null
         end,
         started_at = case
           when p_status = 'RUNNING' then coalesce(started_at, v_now)
           else started_at
         end,
         completed_at = case
           when p_status in ('COMPLETED', 'FAILED', 'CANCELLED') then coalesce(completed_at, v_now)
           else completed_at
         end
   where id = p_job_id;

  if v_job.system_instance_id is null then
    return;
  end if;

  select status
    into v_latest_status
    from public.neroxa_provisioning_jobs
   where system_instance_id = v_job.system_instance_id
   order by created_at desc, id desc
   limit 1;

  if v_latest_status = 'COMPLETED' then
    update public.neroxa_system_instances
       set status = 'ACTIVE',
           updated_at = v_now
     where id = v_job.system_instance_id
       and status <> 'ARCHIVED';
  else
    update public.neroxa_system_instances
       set status = 'PROVISIONING',
           updated_at = v_now
     where id = v_job.system_instance_id
       and status not in ('ARCHIVED', 'SUSPENDED');
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_neroxa_billing_record_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'UPDATE' then
    if new.subscription_id is distinct from old.subscription_id
      or new.reference_month is distinct from old.reference_month
      or new.amount is distinct from old.amount
      or new.organization_id is distinct from old.organization_id
    then
      raise exception 'Dados estruturais da cobrança não podem ser alterados após a criação';
    end if;

    if old.status = 'PENDING' and new.status not in ('PENDING','PAID','OVERDUE','CANCELLED') then
      raise exception 'Transição de cobrança inválida: PENDING -> %', new.status;
    elsif old.status = 'OVERDUE' and new.status not in ('OVERDUE','PAID','CANCELLED') then
      raise exception 'Transição de cobrança inválida: OVERDUE -> %', new.status;
    elsif old.status = 'PAID' and new.status not in ('PAID','REFUNDED') then
      raise exception 'Transição de cobrança inválida: PAID -> %', new.status;
    elsif old.status in ('CANCELLED','REFUNDED') and new.status is distinct from old.status then
      raise exception 'Cobrança em estado terminal não pode ser reaberta';
    end if;
  end if;

  if new.status = 'PAID' then
    if new.paid_at is null then
      raise exception 'Cobrança paga precisa possuir paid_at';
    end if;
  elsif new.status in ('PENDING','OVERDUE','CANCELLED') then
    if new.paid_at is not null then
      raise exception 'Cobrança % não pode possuir paid_at', new.status;
    end if;
  elsif new.status = 'REFUNDED' then
    if new.paid_at is null then
      raise exception 'Cobrança reembolsada precisa possuir paid_at';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_neroxa_contract_proposal_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_proposal public.neroxa_proposals%rowtype;
begin
  if new.proposal_id is null then
    return new;
  end if;

  select *
    into v_proposal
  from public.neroxa_proposals
  where id = new.proposal_id
  for share;

  if not found then
    raise exception 'Proposta vinculada ao contrato não encontrada';
  end if;

  if v_proposal.status <> 'ACCEPTED' then
    raise exception 'Contrato só pode ser criado a partir de proposta aceita';
  end if;

  if new.client_id is distinct from v_proposal.client_id
    or new.plan_id is distinct from v_proposal.plan_id
    or new.system_id is distinct from v_proposal.system_id
    or new.commercial_model is distinct from v_proposal.commercial_model
    or new.billing_period is distinct from v_proposal.billing_period
    or new.recurring_value is distinct from v_proposal.recurring_value
    or new.setup_value is distinct from v_proposal.setup_value
    or new.maintenance_value is distinct from v_proposal.maintenance_value
    or new.currency is distinct from v_proposal.currency
  then
    raise exception 'Dados comerciais do contrato não correspondem à proposta aceita';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_neroxa_contract_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.status = old.status then return new; end if;
  if old.status = 'DRAFT' and new.status = 'ACTIVE' then
    if current_setting('neroxa.allow_contract_activation', true) is distinct from 'true' then
      raise exception 'Ativação de contrato deve ocorrer exclusivamente pelo fluxo oficial de ativação';
    end if;
  elsif old.status = 'DRAFT' and new.status not in ('DRAFT','ACTIVE') then
    raise exception 'Invalid contract transition: % -> %', old.status, new.status;
  elsif old.status = 'ACTIVE' and new.status not in ('SUSPENDED','TERMINATED','EXPIRED') then
    raise exception 'Invalid contract transition: % -> %', old.status, new.status;
  elsif old.status = 'SUSPENDED' and new.status not in ('ACTIVE','TERMINATED','EXPIRED') then
    raise exception 'Invalid contract transition: % -> %', old.status, new.status;
  elsif old.status in ('TERMINATED','EXPIRED') then
    raise exception 'Contract % is final and cannot transition to %', old.status, new.status;
  end if;
  if new.status = 'ACTIVE' and new.signature_status is distinct from 'SIGNED' then raise exception 'Contrato só pode ser ativado após as duas assinaturas'; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_neroxa_proposal_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.status = old.status then
    return new;
  end if;

  if old.status = 'DRAFT' and new.status not in ('SENT','CANCELLED') then
    raise exception 'Invalid proposal transition: % -> %', old.status, new.status;
  end if;
  if old.status = 'SENT' and new.status not in ('NEGOTIATION','ACCEPTED','REJECTED','EXPIRED','CANCELLED') then
    raise exception 'Invalid proposal transition: % -> %', old.status, new.status;
  end if;
  if old.status = 'NEGOTIATION' and new.status not in ('SENT','ACCEPTED','REJECTED','EXPIRED','CANCELLED') then
    raise exception 'Invalid proposal transition: % -> %', old.status, new.status;
  end if;
  if old.status in ('ACCEPTED','REJECTED','EXPIRED','CANCELLED') then
    raise exception 'Proposal % is final and cannot transition to %', old.status, new.status;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_neroxa_subscription_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'UPDATE' then
    if new.organization_id is distinct from old.organization_id
      or new.plan_id is distinct from old.plan_id
      or new.contract_id is distinct from old.contract_id
    then
      raise exception 'Organização, plano e contrato da assinatura não podem ser alterados após a criação';
    end if;

    if old.status = 'TRIAL' and new.status not in ('TRIAL','ACTIVE','CANCELLED','EXPIRED') then
      raise exception 'Transição de assinatura inválida: TRIAL -> %', new.status;
    elsif old.status = 'ACTIVE' and new.status not in ('ACTIVE','PAST_DUE','PAUSED','CANCELLED','EXPIRED') then
      raise exception 'Transição de assinatura inválida: ACTIVE -> %', new.status;
    elsif old.status = 'PAST_DUE' and new.status not in ('PAST_DUE','ACTIVE','PAUSED','CANCELLED') then
      raise exception 'Transição de assinatura inválida: PAST_DUE -> %', new.status;
    elsif old.status = 'PAUSED' and new.status not in ('PAUSED','ACTIVE','CANCELLED') then
      raise exception 'Transição de assinatura inválida: PAUSED -> %', new.status;
    elsif old.status in ('CANCELLED','EXPIRED') and new.status is distinct from old.status then
      raise exception 'Assinatura em estado terminal não pode ser reaberta';
    end if;
  end if;

  if new.current_period_start is not null
    and new.current_period_end is not null
    and new.current_period_end <= new.current_period_start
  then
    raise exception 'O fim do período da assinatura deve ser posterior ao início';
  end if;

  if new.status = 'CANCELLED' then
    if new.cancelled_at is null then
      raise exception 'Assinatura cancelada precisa possuir cancelled_at';
    end if;
  elsif new.cancelled_at is not null then
    raise exception 'Somente assinaturas canceladas podem possuir cancelled_at';
  end if;

  if new.status in ('ACTIVE','PAST_DUE','PAUSED','TRIAL')
    and new.current_period_start is null
  then
    raise exception 'Assinatura em ciclo ativo precisa possuir current_period_start';
  end if;

  if new.status in ('ACTIVE','PAST_DUE','PAUSED','TRIAL')
    and new.current_period_end is null
  then
    raise exception 'Assinatura em ciclo ativo precisa possuir current_period_end';
  end if;

  return new;
end;
$function$
